'use strict';
const legacyAwardRules=[...rules];
let awardRulesReady=false;
function syncAwardRules(saved){rules=saved.filter(r=>r.kind==='loaded_award').map(r=>({...r}));awardRulesReady=true;renderRules();}
async function awardRequest(route,input){const response=await fetch('/api/intelligence'+route,{method:'POST',headers:{'Content-Type':'application/json','X-Sentinel-Action':'scan'},body:JSON.stringify(input)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Award alert save failed');return data;}
async function saveAwardRule(term,minimum){try{await awardRequest('/rules',{kind:'loaded_award',term,minimum});await loadIntelligence();$('ruleTerm').value='';$('awardRuleStatus').textContent='Saved on the local server. Run an award scan to evaluate this rule.';}catch(e){$('awardRuleStatus').textContent=e.message;}}
async function persistLoadedAwards(rows){try{if(!awardRulesReady)throw new Error('Award rules have not loaded; matches could not be saved.');const payload=rows.map(row=>{const value={sub:Boolean(row.sub),amount:row.amount==null?null:Number(row.amount)};for(const key of ['id','name','uei','prime','primeUei','primeId','sourceId','description','date'])value[key]=row[key]==null?null:String(row[key]);return value;});await awardRequest('/loaded-awards',{rows:payload});await loadIntelligence();$('awardRuleStatus').textContent='Loaded award page evaluated; matches and updates saved in the persistent inbox.';}catch(e){$('awardRuleStatus').textContent='Award results loaded, but alert persistence failed: '+e.message;}}
async function importAwardRules(){let imported=0;const completed=readLocal('sentinel.rules.imported',v=>typeof v==='string');try{for(const rule of legacyAwardRules){const signature=JSON.stringify([rule.term.toLowerCase(),rule.minimum]);if(completed.includes(signature))continue;try{await awardRequest('/rules',{kind:'loaded_award',term:rule.term,minimum:rule.minimum});imported++;}catch(e){if(e.message!=='That rule already exists')throw e;}completed.push(signature);if(!persist('sentinel.rules.imported',completed))throw new Error('Import completed, but browser migration marker could not be saved');}await loadIntelligence();if(imported)$('awardRuleStatus').textContent=`Copied ${imported} browser rules to the local server. Browser originals retained as backup.`;}catch(e){$('awardRuleStatus').textContent='Browser rule import incomplete; originals preserved. '+e.message;}}
importAwardRules();
